    wire signed [31:0] c1_ext = {{16{C1[15]}}, C1};
    wire signed [31:0] c2_ext = {{16{C2[15]}}, C2};
    wire signed [31:0] c3_ext = {{16{C3[15]}}, C3};
    wire signed [31:0] c4_ext = {{16{C4[15]}}, C4};
